<?php
require __DIR__.'/bootstrap.php';require_once __DIR__.'/lib/RegistryService.php';
$auth->requireLogin();$church=$auth->currentChurch();if(!$church)redirect('/dashboard.php');
$kind=(string)($_GET['kind']??'person_category');
if(!isset(RegistryService::TYPES[$kind])){http_response_code(404);exit('Cadastro não encontrado.');}
$auth->requireAbility(RegistryService::TYPES[$kind][1]);
$registry=new RegistryService($pdo,$auth,$church['id']);$error=null;$edit=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{verify_csrf();$action=(string)($_POST['action']??'save');
        if($action==='archive'||$action==='restore')$registry->archive($kind,(string)($_POST['id']??''),$action==='archive');
        elseif($action==='save')$registry->save($kind,$_POST);else throw new RuntimeException('Ação inválida.');
        flash('success','Cadastro atualizado.');redirect('/registers.php?kind='.rawurlencode($kind));
    }catch(Throwable $e){$error=$e instanceof PDOException?'Não foi possível salvar. Confira se já existe outro cadastro com esse nome.':$e->getMessage();$edit=['id'=>$_POST['id']??'','name'=>$_POST['name']??'','data'=>$_POST];}
}
if(!empty($_GET['edit']))try{$edit=$registry->find($kind,(string)$_GET['edit'],false);}catch(Throwable $e){$error=$e->getMessage();}
$rows=$registry->all($kind,true);$search=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'active');
$rows=array_values(array_filter($rows,fn($r)=>($status==='all'||(bool)$r['active']===($status==='active'))&&($search===''||mb_stripos($r['name'],$search)!==false)));
$data=$edit['data']??[];$title=RegistryService::TYPES[$kind][0];
View::header($title,$auth,'registers.php');View::flash();
?>
<section class="module-toolbar"><div class="module-title"><h1><?=e($title)?></h1><p>Cadastros da sua igreja. Arquivar mantém os vínculos e o histórico.</p></div><button type="button" class="btn btn-primary" data-open-dialog="register-editor">＋ <?=$edit?'Editar cadastro':'Novo cadastro'?></button></section>
<nav class="portal-tabs" aria-label="Cadastros"><?php foreach(RegistryService::TYPES as $key=>[$label,$ability]):if(!$auth->can($ability))continue;?><a href="?kind=<?=e($key)?>" <?=$key===$kind?'aria-current="page"':''?>><?=e($label)?></a><?php endforeach?></nav>
<?php if($error):?><div class="alert alert-error" role="alert"><?=e($error)?></div><?php endif?>
<section class="card card-pad"><form class="portal-filter" method="get"><input type="hidden" name="kind" value="<?=e($kind)?>"><label>Pesquisar<input class="input" name="q" value="<?=e($search)?>"></label><label>Situação<select class="select" name="status"><?php foreach(['active'=>'Ativos','archived'=>'Arquivados','all'=>'Todos'] as $value=>$label):?><option value="<?=e($value)?>" <?=$status===$value?'selected':''?>><?=e($label)?></option><?php endforeach?></select></label><button class="btn btn-light">Filtrar</button></form>
<div class="table-wrap"><table class="table"><thead><tr><th>Nome</th><th>Detalhes</th><th>Situação</th><th>Ações</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?=e($row['name'])?></strong><?php if($kind==='family'):?><div><a href="/members.php?family_id=<?=e($row['id'])?>">Ver membros desta família</a></div><?php endif?></td><td><?=e($row['data']['notes']??'')?><?php if($kind==='contact'||$kind==='family'):?><div><?=e($row['data']['phone']??'')?> · <?=e($row['data']['email']??'')?></div><?php endif?></td><td><?=$row['active']?'Ativo':'Arquivado'?></td><td><div class="actions"><a class="btn btn-light" href="?kind=<?=e($kind)?>&edit=<?=e($row['id'])?>">Editar</a><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($row['id'])?>"><input type="hidden" name="action" value="<?=$row['active']?'archive':'restore'?>"><button class="btn btn-light"><?=$row['active']?'Arquivar':'Restaurar'?></button></form></div></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="4"><div class="empty">Nenhum cadastro encontrado. Use Novo cadastro para começar.</div></td></tr><?php endif?></tbody></table></div></section>
<dialog class="app-dialog" id="register-editor" aria-labelledby="register-title" <?=($edit||$error)?'data-auto-open':''?>><div class="dialog-shell"><header class="dialog-heading"><div><h2 id="register-title"><?=$edit?'Editar cadastro':'Novo cadastro'?></h2><p><?=e($title)?></p></div><button type="button" class="icon-button" data-close-dialog aria-label="Fechar">×</button></header><div class="dialog-body"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-grid"><label class="full">Nome *<input class="input" name="name" value="<?=e($edit['name']??'')?>" maxlength="190" required></label>
<?php if($kind==='finance_category'):?><label class="full">Tipo<select class="select" name="direction"><?php foreach(['both'=>'Entrada e saída','income'=>'Somente entradas','expense'=>'Somente saídas'] as $value=>$label):?><option value="<?=e($value)?>" <?=($data['direction']??'both')===$value?'selected':''?>><?=e($label)?></option><?php endforeach?></select></label><?php endif?>
<?php if($kind==='contact'||$kind==='family'):foreach(['responsible'=>'Responsável','phone'=>'Telefone','email'=>'E-mail','document'=>'CPF/CNPJ (opcional)'] as $key=>$label):?><label><?=e($label)?><input class="input" name="<?=e($key)?>" value="<?=e($data[$key]??'')?>" type="<?=$key==='email'?'email':'text'?>"></label><?php endforeach;endif?>
<?php if($kind==='custom_field'):?><label>Tipo<select class="select" name="field_type"><?php foreach(['text'=>'Texto','date'=>'Data','number'=>'Número','choice'=>'Lista de opções'] as $value=>$label):?><option value="<?=e($value)?>" <?=($data['type']??$data['field_type']??'text')===$value?'selected':''?>><?=e($label)?></option><?php endforeach?></select></label><label><input type="checkbox" name="required" <?=!empty($data['required'])?'checked':''?>> Preenchimento obrigatório</label><label class="full">Opções (uma por linha, para listas)<textarea class="textarea" name="options"><?=e(is_array($data['options']??null)?implode("\n",$data['options']):($data['options']??''))?></textarea></label><?php endif?>
<label class="full">Observações<textarea class="textarea" name="notes" maxlength="4000"><?=e($data['notes']??'')?></textarea></label></div><button class="btn btn-primary">Salvar cadastro</button></form></div></div></dialog>
<?php View::footer();
